_DEFAULT_VERSION = "v3.1"


def set_catalog_version(version: str):
    """Set the default catalog version for the current session/notebook.

    Parameters
    ----------
    version : str
        Catalog version string, e.g. ``'v3.1'``, ``'v3'``, ``'v1'``.

    Examples
    --------
    >>> set_catalog_version('v3.1')
    """
    global _DEFAULT_VERSION
    _DEFAULT_VERSION = version


@contextmanager
def catalog_version(version: str):
    """Context manager to temporarily use a different catalog version.

    Parameters
    ----------
    version : str
        Catalog version string, e.g. ``'v3.1'``, ``'v3'``, ``'v1'``.

    Examples
    --------
    >>> with catalog_version('v3'):
    ...     fans = get_fan_catalog()
    """
    global _DEFAULT_VERSION
    old = _DEFAULT_VERSION
    _DEFAULT_VERSION = version
    try:
        yield
    finally:
        _DEFAULT_VERSION = old


def _resolve_version(version):
    "Return version if explicitly given, otherwise fall back to _DEFAULT_VERSION. Normalises e.g. 'v1.0' → 'v1'."
    v = version if version is not None else _DEFAULT_VERSION
    if v not in fetchers and v.endswith(".0"):
        v = v[:-2]  # strip trailing .0: v1.0 → v1, v3.0 → v3
    return v

