def get_metafull(version=None) -> pd.DataFrame:
    "only v3 and v3.1 exist"
    version = _resolve_version(version)
    fetch = fetchers[version] if version in ("v3", "v3.1") else fetchers["v3"]
    df = pd.read_parquet(fetch("metafull", **kwargs)).drop("Unnamed: 0", axis=1, errors="ignore")
    return define_martian_year(df, "OBSERVATION_START_TIME")


def get_blotch_catalog(version=None) -> pd.DataFrame:
    version = _resolve_version(version)
    bl = pd.read_parquet(fetchers[version]("blotches", **kwargs))
    meta = get_metafull(version)
    return bl.set_index("obsid").join(meta.set_index("OBSERVATION_ID")["MY"]).reset_index()


def get_fan_catalog(version=None) -> pd.DataFrame:
    version = _resolve_version(version)
    fans = pd.read_parquet(fetchers[version]("fans", **kwargs))
    meta = get_metafull(version)
    return fans.set_index("obsid").join(meta.set_index("OBSERVATION_ID")["MY"]).reset_index()


def get_tile_coords(version=None) -> pd.DataFrame:
    version = _resolve_version(version)
    return pd.read_parquet(fetchers[version]("tile_coords", **kwargs))


def get_meta_data(version=None) -> pd.DataFrame:
    version = _resolve_version(version)
    return pd.read_parquet(fetchers[version]("metadata", **kwargs))


def get_region_names(version=None) -> pd.DataFrame:
    """Per-obsid ROI assignments.

    v3.1 (default) includes the 11 MY-33 obsids that are missing from the
    v1 mapping (5 Manhattan_Classic + 6 Ithaca). v1 is kept available for
    historical reproduction.
    """
    version = _resolve_version(version) if version is not None else "v3.1"
    if version in ("v3", "v3.1"):
        return pd.read_parquet(fetchers["v3.1"]("region_names", **kwargs))
    if version == "v1":
        return pd.read_parquet(v1.fetch("region_names", **kwargs))
    raise ValueError(f"region_names not available for version {version!r}")


def get_tile_urls() -> pd.DataFrame:
    "only v1 exists"
    return pd.read_parquet(v1.fetch("tile_urls", **kwargs))


