# %% ../notebooks/00_io.ipynb #c9f4d1e7
def get_cached_tile_ids():
    """Reverse-map the local subframe cache to the tile_ids available offline.

    Scans the pooch tiles cache (``pooch.os_cache("p4tools/tiles")``), where each
    file is named ``<md5(url)>-<subject>.jpg``, and maps it back to its tile_id via
    `get_tile_urls`. Only files whose name matches ``pooch.utils.unique_file_name``
    of the looked-up URL are counted, so stray files are ignored.

    Returns
    -------
    list of str
        Sorted tile_ids whose subframe image is present in the local cache.
    """
    cache_dir = Path(pooch.os_cache("p4tools/tiles"))
    if not cache_dir.exists():
        return []
    urls = _tile_url_series()
    # subject-basename -> tile_id; basenames are unique in the table
    base2tid = {u.rsplit("/", 1)[-1]: tid for tid, u in urls.items()}
    found = []
    for f in cache_dir.iterdir():
        if not f.is_file() or "-" not in f.name:
            continue
        tid = base2tid.get(f.name.split("-", 1)[1])
        if tid is not None and f == _cache_path_for_url(urls.at[tid]):
            found.append(tid)
    return sorted(found)

# %% ../notebooks/00_io.ipynb #c8dfc110
def get_fans_for_tile(tile_id, version=None):
    version = _resolve_version(version)
    tile_id = normalize_tile_id(tile_id)
    fans = get_fan_catalog(version)
    result = fans.query("tile_id == @tile_id")
    if result.empty:
        tc = get_tile_coords(version)
        if tile_id not in tc["tile_id"].values:
            warnings.warn(
                f"Tile {tile_id} is not in the {version} catalog — its observation "
                f"was not included in this release. Try a different version.",
                UserWarning, stacklevel=2,
            )
    return result

# %% ../notebooks/00_io.ipynb #041e25b4
def get_blotches_for_tile(tile_id, version=None):
    version = _resolve_version(version)
    tile_id = normalize_tile_id(tile_id)
    blotches = get_blotch_catalog(version)
    result = blotches.query("tile_id == @tile_id")
    if result.empty:
        tc = get_tile_coords(version)
        if tile_id not in tc["tile_id"].values:
            warnings.warn(
                f"Tile {tile_id} is not in the {version} catalog — its observation "
                f"was not included in this release. Try a different version.",
                UserWarning, stacklevel=2,
            )
    return result

# %% ../notebooks/00_io.ipynb #89e455cd
def get_hirise_id_for_tile(tile_id, version=None):
    version = _resolve_version(version)
    tile_id = normalize_tile_id(tile_id)
    try:
        obsid = get_fans_for_tile(tile_id, version).obsid.iloc[0]
    except IndexError:
        try:
            obsid = (
                get_blotch_catalog(version).query("tile_id == @tile_id").obsid.iloc[0]
            )
        except IndexError:
            raise ValueError(f"No obsid found for tile {tile_id}")
    else:
        return obsid

